const colors=['#aeb68a','#708269','#5b715f','#95a18a'];
function rand(a,b){return a+Math.random*(b-a)}
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key==='Escape')togglePause()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('mousedown',()=>mouse.down=true);addEventListener('mouseup',()=>mouse.down=false);
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function start(){document.getElementById('start').classList.add('hidden');document.getElementById('gameover').classList.add('hidden');reset();game=true;paused=false;requestAnimationFrame(loop)}
function reset(){level=1;score=0;p.x=W/2;p.y=H/2;p.hp=p.maxHp;p.en=0;p.damage=24;p.rate=.32;p.pierce=0;p.dashCd=0;bullets=[];enemies=[];particles=[];texts=[];boss=null;obstacles=[];for(let i=0;i<18;i++)obstacles.push({x:rand(100,W-100),y:rand(120,H-100),w:rand(35,75),h:rand(28,55)});updateHud();spawnTimer=1}
function togglePause(){if(!game)return paused=!paused,document.getElementById('pause').classList.toggle('hidden',!paused)}
function shoot(){if(p.fireCd>0)return;const a=Math.atan2(mouse.y-p.y,mouse.x-p.x);p.angle=a;p.fireCd=p.rate;bullets.push({x:p.x+Math.cos(a)*22,y:p.y+Math.sin(a)*22,vx:Math.cos(a)*520,vy:Math.sin(a)*520,r:5,life:1.2,pierce:p.pierce,damage:p.damage})}
function dash(){if(p.dashCd>0)return;const kx=(keys.d?1:0)-(keys.a?1:0),ky=(keys.s?1:0)-(keys.w?1:0);let a=kx||ky?Math.atan2(ky,kx):p.angle;p.dash=.16;p.dashCd=1.5;p.x+=Math.cos(a)*35;p.y+=Math.sin(a)*35}
function update(dt){if(paused)return;p.dashCd=Math.max(0,p.dashCd-dt);p.fireCd=Math.max(0,p.fireCd-dt);p.dash=Math.max(0,p.dash-dt);let kx=(keys.d?1:0)-(keys.a?1:0),ky=(keys.s?1:0)-(keys.w?1:0);if(touchMove.active){kx=touchMove.dx;ky=touchMove.dy}let l=Math.hypot(kx,ky);if(l){kx/=l||1;ky/=l||1;p.x+=kx*p.speed*(p.dash>0?3:1)*dt;p.y+=ky*p.speed*(p.dash>0?3:1)*dt;p.angle=Math.atan2(ky,kx)}p.x=Math.max(25,Math.min(W-25,p.x));p.y=Math.max(105,Math.min(H-25,p.y));if(mouse.down)shoot();for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt}bullets=bullets.filter(b=>b.life>0&&b.x>-30&&b.x<W+30&&b.y>70&&b.y<H+30);
spawnTimer-=dt;if(spawnTimer<=0&&enemies.length<Math.min(5+level,16)&&!boss){spawnTimer=Math.max(.25,1.2-level*.07);spawnEnemy()}for(let e of enemies){let a=Math.atan2(p.y-e.y,p.x-e.x);let sp=e.speed*(boss?1:1);e.x+=Math.cos(a)*sp*dt;e.y+=Math.sin(a)*sp*dt;e.attack-=dt;if(dist(e,p)<e.r+p.r){if(e.attack<=0){damage(10+(level-1)*2);e.attack=1}}if(e.shoot&&e.attack<=0){bullets.push({x:e.x,y:e.y,vx:Math.cos(a)*250,vy:Math.sin(a)*250,r:7,life:3,enemy:true,damage:12});e.attack=2}}
for(let b of bullets)if(b.enemy&&dist(b,p)<b.r+p.r){b.life=0;damage(b.damage)}for(let b of bullets)for(let e of enemies){if(!b.enemy&&dist(b,e)<b.r+e.r){e.hp-=b.damage;b.pierce?(b.pierce--):(b.life=0);particles.push({x:b.x,y:b.y,vx:rand(-70,70),vy:rand(-70,70),life:.25,c:'#f3c75d'});if(e.hp<=0)e.dead=true}}
enemies=enemies.filter(e=>!e.dead);for(let e of [...enemies])if(e.dead===true){score+=e.score;p.en=Math.min(100,p.en+e.score/4);spawnBurst(e.x,e.y,'#9b9d72');texts.push({x:e.x,y:e.y,t:'+'+e.score,life:.8})}if(p.en>=100&&!boss&&level<5){p.en=0;levelUp()}shake*=.88;particles.forEach(q=>{q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt});particles=particles.filter(q=>q.life>0);texts.forEach(t=>{t.y-=25*dt;t.life-=dt});texts=texts.filter(t=>t.life>0);updateHud()}
function damage(n){if(p.dash>0)return;p.hp-=n;shake=8;if(p.hp<=0)p.hp=0,endGame(false)}
function spawnEnemy(){let side=Math.floor(Math.random()*4),x=side===0?-30:side===1?W+30:rand(30,W-30),y=side===2?-30:side===3?H+30:rand(120,H-30);let big=level>=3&&Math.random()<.12;enemies.push({x,y,r:big?24:13,hp:big?80:35+level*8,speed:big?35:55+level*7,score:big?25:10,attack:rand(.2,1),shoot:level>=2&&Math.random()<.18,big})}
