function levelUp(){paused=true;document.getElementById('levelup').classList.remove('hidden');const cards=[['✦','Sharper Stapler','Damage +8','damage'],['♥','Extra Vacation','Maximum health +25','health'],['»','Rapid Refill','Fire rate 30% faster','speed'],['◆','Triple Shift','Bullets pierce 1 target','pierce']];let picks=cards.sort(()=>Math.random-.5).slice(0,3);let el=document.getElementById('cards');el.innerHTML='';picks.forEach(c=>{let d=document.createElement('button');d.className='perk';d.innerHTML=`<i>${c[0]}</i><b>${c[1]}</b><p>${c[2]}</p>`;d.onclick=()=>{if(c[3]==='damage')p.damage+=8;if(c[3]==='health'){p.maxHp+=25;p.hp+=25}if(c[3]==='speed')p.rate*=.7;if(c[3]==='pierce')p.pierce++;document.getElementById('levelup').classList.add('hidden');paused=false;level++;toast('FLOOR '+level+' · '+c[1].toUpper());bullets=[];enemies=[]};el.appendChild(d)})}
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.style.opacity=1;clearTimeout(t.hide);t.hide=setTimeout(()=>t.style.opacity=0,1800)}
function endGame(win){game=false;document.getElementById('gameover').classList.remove('hidden');document.getElementById('endTitle').textContent=win?'SHIFT COMPLETE':'YOU DIED';document.getElementById('endText').textContent='Score '+score+' · Floor '+level}
