function draw(){ctx.save();ctx.translate(rand(-shake,shake),rand(-shake,shake));let tile=38;ctx.fillStyle='#69745c';ctx.fillRect(0,0,W,H);for(let y=90;y<H;y+=tile)for(let x=-tile;x<W;x+=tile){let a=((x/tile+y/tile)&1);ctx.fillStyle=a?'#737d66':'#6a745f';ctx.fillRect(x,y,tile,tile);ctx.strokeStyle='rgba(45,60,48,.12)';ctx.strokeRect(x+1,y+1,tile-2,tile-2)}ctx.fillStyle='#38483b';ctx.fillRect(0,0,W,90);ctx.fillStyle='#4b5b48';for(let x=0;x<W;x+=95){ctx.fillRect(x,20,72,52);ctx.fillStyle='#26352b';ctx.fillRect(x+8,28,56,36);ctx.fillStyle='#9e9f78';ctx.fillRect(x+12,32,48,28);ctx.fillStyle='#4b5b48'}for(let o of obstacles){ctx.fillStyle='#9b9a77';ctx.fillRect(o.x,o.y,o.w,o.h);ctx.strokeStyle='#59654e';ctx.lineWidth=4;ctx.strokeRect(o.x,o.y,o.w,o.h)}for(let b of bullets){ctx.fillStyle=b.enemy?'#c95a43':'#f4d96e';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,7);ctx.fill()}for(let e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle=e.big?'#4c2e29':'#626b55';ctx.beginPath();ctx.ellipse(0,8,e.r,e.r*.75,0,0,7);ctx.fill();ctx.fillStyle='#d2aa82';ctx.beginPath();ctx.arc(0,-e.r*.25,e.r*.65,0,7);ctx.fill();ctx.fillStyle='#242d26';ctx.fillRect(-e.r*.35,-e.r*.35,e.r*.18,e.r*.18);ctx.fillRect(e.r*.17,-e.r*.35,e.r*.18,e.r*.18);ctx.restore()}ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle='#202820';ctx.beginPath();ctx.ellipse(-4,8,17,22,0,0,7);ctx.fill();ctx.fillStyle='#d9b98b';ctx.beginPath();ctx.arc(0,-7,13,0,7);ctx.fill();ctx.fillStyle='#2e3b32';ctx.fillRect(5,-12,28,7);ctx.fillStyle='#d8c88f';ctx.fillRect(25,-14,17,11);ctx.restore();for(let q of particles){ctx.globalAlpha=Math.max(0,q.life*3);ctx.fillStyle=q.c;ctx.fillRect(q.x,q.y,4,4)}ctx.globalAlpha=1;ctx.font='bold 12px Trebuchet MS';ctx.textAlign='center';for(let t of texts){ctx.fillStyle='#f4df8a';ctx.fillText(t.t,t.x,t.y)}ctx.restore()}
let touchMove={active:false,dx:0,dy:0};const joy=document.getElementById('joystick'),stick=document.getElementById('stick');joy.addEventListener('pointerdown',e=>{joy.setPointerCapture(e.pointerId);touchMove.active=true;joyMove(e)});joy.addEventListener('pointermove',e=>{if(touchMove.active)joyMove(e)});joy.addEventListener('pointerup',()=>{touchMove.active=false;touchMove.dx=0;touchMove.dy=0;stick.style.transform='translate(0,0)' });function joyMove(e){let r=joy.getBoundingRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,l=Math.hypot(dx,dy),m=35;if(l>m){dx=dx/l*m;dy=dy/l*m}touchMove.dx=dx/m;touchMove.dy=dy/m;stick.style.transform=`translate(${dx}px,${dy}px)`}
